#### Python (pytest-bdd) example

```python
# tests/cache/adapters/test_redis_cache.py
"""BDD contract verification for RedisCache adapter."""

import pytest
from pytest_bdd import scenarios, given, when, then

from myapp.cache.adapters.redis_cache import RedisCache

# Load ALL scenarios from the canonical feature file
scenarios("../../../../docs/requirements/functional/cache/core.feature")


@pytest.fixture
def cache():
    """Provide a RedisCache instance connected to test Redis."""
    adapter = RedisCache(host="localhost", port=6379, db=15)
    adapter.flush()
    yield adapter
    adapter.flush()


@given("the cache is empty", target_fixture="cache_state")
def given_empty_cache(cache):
    cache.flush()
    return cache


@when("an item is stored with key {key} and value {value}")
def when_item_stored(cache, key, value):
    cache.set(key, value)


@then("retrieving key {key} returns {value}")
def then_key_returns(cache, key, value):
    assert cache.get(key) == value
```

