# tests/cache/adapters/test_memory_cache.py
"""BDD contract verification for InMemoryCache adapter."""

import pytest
from pytest_bdd import scenarios, given, when, then

from myapp.cache.adapters.memory_cache import InMemoryCache

# Load the SAME scenarios — same contract, different adapter
scenarios("../../../../docs/requirements/functional/cache/core.feature")


@pytest.fixture
def cache():
    """Provide a fresh InMemoryCache instance."""
    return InMemoryCache()


@given("the cache is empty", target_fixture="cache_state")
def given_empty_cache(cache):
    cache.flush()
    return cache


@when("an item is stored with key {key} and value {value}")
def when_item_stored(cache, key, value):
    cache.set(key, value)


@then("retrieving key {key} returns {value}")
def then_key_returns(cache, key, value):
    assert cache.get(key) == value
```

