#### C# (Reqnroll) example

```csharp
// Tests/Cache/Adapters/RedisCacheSteps.cs
[Binding]
[Scope(Tag = "redis")]
public class RedisCacheSteps
{
    private readonly RedisCache _cache;

    public RedisCacheSteps()
    {
        _cache = new RedisCache("localhost:6379,defaultDatabase=15");
        _cache.Flush();
    }

    [Given("the cache is empty")]
    public void GivenTheCacheIsEmpty() => _cache.Flush();

    [When("an item is stored with key {string} and value {string}")]
    public void WhenItemStored(string key, string value) => _cache.Set(key, value);

    [Then("retrieving key {string} returns {string}")]
    public void ThenKeyReturns(string key, string value) =>
        Assert.Equal(value, _cache.Get(key));
}
```
